    let request = json!({"type":"object","properties":{"url":{"type":"string","minLength":1,"maxLength":8192},"method":{"type":"string"},"headers":{"type":"object","additionalProperties":{"type":"string"}},"body":{"type":"string","maxLength":1048576}},"required":["url"],"additionalProperties":false});
